// Tìm nháp + kiểm tra trạng thái + DỰNG EMAIL CHỈ TỪ PHẦN CÔNG KHAI.
// P2: internal_json (biên, giá gốc nhà xe) TUYỆT ĐỐI không đưa vào email.
const draftId = $('Nhận lệnh duyệt').first().json.query.draft_id;
if (!draftId) throw new Error('Thiếu draft_id');

const rows = $input.all().map(i => i.json);
const d = rows.find(r => String(r.id) === String(draftId));
if (!d) throw new Error('Không tìm thấy nháp ' + draftId);
if (d.status !== 'pending') {
  // Idempotent: bấm link 2 lần không gửi email 2 lần.
  return [{ json: { already: true, status: d.status, draft_id: draftId } }];
}
if (!d.customer_email) throw new Error('Nháp ' + draftId + ' thiếu email khách');

const vn = n => new Intl.NumberFormat('vi-VN').format(Number(n));
let surchargeLines = '';
try {
  const ss = JSON.parse(d.surcharges_json || '[]');
  if (ss.length) {
    surchargeLines = '\nPhụ phí (đã gồm trong giá):\n' +
      ss.map(s => '  - ' + s.name + ': ' + vn(s.value) + ' đ').join('\n');
  }
} catch (e) { /* surcharges_json hỏng thì bỏ qua phần liệt kê */ }

const emailBody =
  'Kính gửi ' + (d.customer_name || 'Quý khách') + ',\n\n' +
  'Chúng tôi xin gửi báo giá vận chuyển theo yêu cầu:\n\n' +
  '  Tuyến: ' + d.origin + ' → ' + d.destination + '\n' +
  '  Loại xe: ' + d.vehicle_type + (d.cargo_type ? '\n  Loại hàng: ' + d.cargo_type : '') +
  (d.pickup_date ? '\n  Ngày lấy hàng dự kiến: ' + d.pickup_date : '') + '\n\n' +
  '  TỔNG CƯỚC: ' + vn(d.quoted_price) + ' đ (đã gồm VAT nếu có thoả thuận)\n' +
  surchargeLines + '\n\n' +
  'Báo giá có hiệu lực trong 48 giờ do giá nhiên liệu biến động.\n' +
  'Quý khách xác nhận vui lòng phản hồi email này.\n\nTrân trọng.';

return [{ json: {
  already: false, draft_id: draftId,
  to: d.customer_email,
  subject: 'Báo giá vận chuyển ' + d.origin + ' - ' + d.destination + ' [' + draftId + ']',
  body: emailBody,
  row_id: d.id
}}];
